import{_ as d,o as e,c as o,a3 as a}from"./chunks/framework.BLaSdaBb.js";const g=JSON.parse('{"title":"任务调度","description":"","frontmatter":{},"headers":[],"relativePath":"backend/scheduling.md","filePath":"backend/scheduling.md","lastUpdated":1786258579000}'),r={name:"backend/scheduling.md"};function c(n,t,s,i,l,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="任务调度" tabindex="-1">任务调度 <a class="header-anchor" href="#任务调度" aria-label="Permalink to &quot;任务调度&quot;">​</a></h1><p>页面 <code>/setting/job</code>，实体 <code>SysTask</code> + <code>SysTaskLog</code>（按月分表）。它是框架 <a href="https://framework.docs.xihanfun.com/packages/tasks" target="_blank" rel="noreferrer">Tasks 调度引擎</a> 的<strong>管理面</strong>：把任务定义落库、在页面上启停与手动触发，执行仍由框架的调度器完成。</p><h2 id="数据模型" tabindex="-1">数据模型 <a class="header-anchor" href="#数据模型" aria-label="Permalink to &quot;数据模型&quot;">​</a></h2><p><code>SysTask</code> 的字段分四组：</p><h3 id="标识与执行目标" tabindex="-1">标识与执行目标 <a class="header-anchor" href="#标识与执行目标" aria-label="Permalink to &quot;标识与执行目标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>TaskCode</code> / <code>TaskName</code> / <code>TaskDescription</code></td><td>编码、名称、描述</td></tr><tr><td><code>TaskGroup</code></td><td>分组，便于按业务域归类</td></tr><tr><td><code>TaskClass</code></td><td><strong>执行类的类型名</strong>——调度器据此解析出 <code>IJobWorker</code></td></tr><tr><td><code>TaskMethod</code></td><td>方法名（按需）</td></tr><tr><td><code>TaskParams</code></td><td>参数（JSON 字符串），执行时注入上下文</td></tr></tbody></table><h3 id="触发方式" tabindex="-1">触发方式 <a class="header-anchor" href="#触发方式" aria-label="Permalink to &quot;触发方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>默认</th></tr></thead><tbody><tr><td><code>TriggerType</code></td><td><code>Immediate</code> / Cron / 间隔 等</td><td><code>Immediate</code></td></tr><tr><td><code>CronExpression</code></td><td>Cron 表达式（<code>TriggerType</code> 为 Cron 时用）</td><td>—</td></tr><tr><td><code>IntervalSeconds</code></td><td>固定间隔秒数</td><td>—</td></tr><tr><td><code>StartTime</code> / <code>EndTime</code></td><td>生效窗口</td><td>—</td></tr><tr><td><code>RepeatCount</code></td><td>重复次数上限，<strong><code>-1</code> 表示不限</strong></td><td><code>-1</code></td></tr><tr><td><code>NextRunTime</code> / <code>LastRunTime</code> / <code>ExecutedCount</code></td><td>运行时游标</td><td>—</td></tr></tbody></table><p>前端用 <code>CronExpression.vue</code> 组件（输入框 + 可视化弹窗）编辑 Cron，不必手写表达式。</p><h3 id="执行控制" tabindex="-1">执行控制 <a class="header-anchor" href="#执行控制" aria-label="Permalink to &quot;执行控制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>默认</th></tr></thead><tbody><tr><td><code>TimeoutSeconds</code></td><td>单次执行超时</td><td><code>300</code></td></tr><tr><td><strong><code>AllowConcurrent</code></strong></td><td><strong>是否允许并发重入</strong></td><td><code>false</code></td></tr><tr><td><code>RetryCount</code> / <code>MaxRetryCount</code></td><td>已重试 / 最大重试</td><td><code>0</code> / <code>3</code></td></tr><tr><td><code>Priority</code></td><td>优先级</td><td><code>0</code></td></tr><tr><td><code>RunTaskStatus</code></td><td>运行状态（<code>Pending</code> / <code>Running</code> / …）</td><td><code>Pending</code></td></tr><tr><td><code>Status</code></td><td>启用状态</td><td><code>Enabled</code></td></tr></tbody></table><h2 id="启动时同步" tabindex="-1">启动时同步 <a class="header-anchor" href="#启动时同步" aria-label="Permalink to &quot;启动时同步&quot;">​</a></h2><p>Saas 模块在 <code>OnPostApplicationInitialization</code>（<strong>所有模块都就绪之后</strong>）做两件事：</p><ol><li>扫描代码里声明式定义的任务；</li><li>把数据库中<strong>活跃的</strong> <code>SysTask</code> 同步进调度器。</li></ol><p>同时<strong>复位崩溃残留的 <code>Running</code> 状态</strong>——进程被杀时正在跑的任务会永远停在 <code>Running</code>，既不会被再次触发（<code>AllowConcurrent=false</code> 时会被判为「已在运行」而跳过），也不会自己结束。不复位就等于这个任务从此再也不执行了。</p><div class="warning custom-block"><p class="custom-block-title">新加的任务没跑起来</p><p>按顺序查：</p><ol><li><code>Status</code> 是不是 <code>Enabled</code>；</li><li><code>TaskClass</code> 能不能解析到实际类型（改过命名空间/类名？）；</li><li>Cron 表达式算不算得出下次时间——<strong>算不出时任务会「注册了但永不执行」</strong>，框架会打 Warning 日志，去日志里搜；</li><li><code>EndTime</code> 是不是已经过了、<code>RepeatCount</code> 是不是已经用完；</li><li><code>RunTaskStatus</code> 是不是卡在 <code>Running</code>（崩溃残留没复位）。</li></ol></div><h2 id="并发与多实例" tabindex="-1">并发与多实例 <a class="header-anchor" href="#并发与多实例" aria-label="Permalink to &quot;并发与多实例&quot;">​</a></h2><p><code>AllowConcurrent = false</code> 依赖任务锁防止重入。<strong>跨实例防并发需要 Redis</strong>——框架的锁来自 Caching，未接 Redis 时退化为进程内锁，多实例部署会各跑各的。</p><p>生产多实例部署时这一点务必确认，否则会出现「日报表发了三份」这类问题。</p><h2 id="多租户" tabindex="-1">多租户 <a class="header-anchor" href="#多租户" aria-label="Permalink to &quot;多租户&quot;">​</a></h2><p>任务执行时会切换到正确的租户上下文（<code>ICurrentTenant.Change</code>），解析优先级是：参数里的 <code>tenantId</code> → <code>SysTask</code> 的租户归属 → 当前异步上下文租户。宿主级任务的租户为空。</p><p>这意味着<strong>同一个任务类可以被不同租户各配一份</strong>，各自跑在自己的数据范围里。</p><h2 id="执行日志" tabindex="-1">执行日志 <a class="header-anchor" href="#执行日志" aria-label="Permalink to &quot;执行日志&quot;">​</a></h2><p><code>SysTaskLog</code>（<code>Sys_Task_Log_{yyyyMM}</code>，按月分表）记录每次执行的开始/结束、耗时、结果与异常。分表数据要走 SqlSugar 的分表 API 按时间范围查，不能当普通表直接查。</p><h2 id="与其它异步机制的分工" tabindex="-1">与其它异步机制的分工 <a class="header-anchor" href="#与其它异步机制的分工" aria-label="Permalink to &quot;与其它异步机制的分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>用什么</th></tr></thead><tbody><tr><td><strong>周期性/定时触发</strong>（每天凌晨跑报表）</td><td><strong>本页的任务调度 + <code>SysTask</code></strong></td></tr><tr><td>一次性 fire-and-forget，入队即返回</td><td>框架 <code>IBackgroundJobManager.EnqueueAsync</code></td></tr><tr><td>持续拉队列消费、业务表做状态机</td><td><code>XiHanBackgroundServiceBase&lt;T&gt;</code> + <code>IRedisDelayQueue&lt;T&gt;</code>（发件箱、导出走这条）</td></tr><tr><td>等人审批的长流程</td><td><a href="./workflow">工作流</a></td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="https://framework.docs.xihanfun.com/packages/tasks" target="_blank" rel="noreferrer">框架 · Tasks</a>：调度引擎、中间件管道、声明式特性</li><li><a href="./caching">缓存与异步</a>：另外两条异步链路</li><li><a href="./data-model#文件与任务">数据模型</a>：表结构</li></ul>',28)])])}const b=d(r,[["render",c]]);export{g as __pageData,b as default};
